/**
 * Types describing the streaming agent protocol used by the core package.
 *
 * An {@link AgentSession} accepts a payload via {@link AgentSession.send} and
 * produces an ordered stream of {@link AgentEvent}s that can be consumed with
 * {@link AgentSession.stream}. Every event belongs to a single stream and is
 * tagged with a `streamId` and a unique `id`.
 */

/** The role attached to a `message` event. */
export type MessageRole = 'user' | 'assistant' | 'system';

/** A single piece of message content. */
export interface ContentPart {
  type: string;
  text?: string;
  [key: string]: unknown;
}

/** A message exchanged with the agent. */
export interface AgentMessage {
  role?: MessageRole;
  content?: ContentPart[] | string;
  [key: string]: unknown;
}

/** A response to a previously requested elicitation. */
export interface ElicitationResponse {
  id?: string;
  content?: unknown;
  [key: string]: unknown;
}

/** A partial update to the session's properties. */
export type SessionUpdatePayload = Record<string, unknown>;

/** An imperative action requested by the caller. */
export interface AgentAction {
  type: string;
  [key: string]: unknown;
}

/**
 * The payload accepted by {@link AgentSession.send}. Exactly one of the
 * properties must be provided.
 */
export type AgentSend =
  | { message: AgentMessage; elicitations?: never; update?: never; action?: never }
  | {
      elicitations: ElicitationResponse[];
      message?: never;
      update?: never;
      action?: never;
    }
  | {
      update: SessionUpdatePayload;
      message?: never;
      elicitations?: never;
      action?: never;
    }
  | { action: AgentAction; message?: never; elicitations?: never; update?: never };

/** The reason a stream was ended. */
export type StreamEndReason = 'completed' | 'aborted' | 'failed';

/** Fields shared by every {@link AgentEvent}. */
export interface BaseAgentEvent {
  /** Unique identifier for the event within the session. */
  id: string;
  /** Identifier of the stream the event belongs to. */
  streamId: string;
}

/** Emitted once at the beginning of a stream. */
export interface StreamStartEvent extends BaseAgentEvent {
  type: 'stream_start';
}

/** Emitted once at the end of a stream. */
export interface StreamEndEvent extends BaseAgentEvent {
  type: 'stream_end';
  reason?: StreamEndReason;
}

/** A message emitted on the stream. */
export interface MessageEvent extends BaseAgentEvent {
  type: 'message';
  role: MessageRole;
  content?: ContentPart[] | string;
}

/** Emitted when the session's properties change. */
export interface SessionUpdateEvent extends BaseAgentEvent {
  type: 'session_update';
  [key: string]: unknown;
}

/** Emitted in response to an elicitation. */
export interface ElicitationResponseEvent extends BaseAgentEvent {
  type: 'elicitation_response';
  [key: string]: unknown;
}

/** The discriminated union of every event that can appear on a stream. */
export type AgentEvent =
  | StreamStartEvent
  | StreamEndEvent
  | MessageEvent
  | SessionUpdateEvent
  | ElicitationResponseEvent;

/**
 * A streaming agent session. Implementations accept payloads and produce an
 * ordered stream of {@link AgentEvent}s.
 */
export interface AgentSession {
  /**
   * Send a payload to the agent, starting a new stream. Resolves with the
   * `streamId` of the newly created stream.
   */
  send(payload: AgentSend): Promise<{ streamId: string }>;

  /**
   * Iterate over the events of a stream. When no `streamId` is provided the
   * most recently created stream is used. When an `eventId` is provided the
   * iteration resumes with the event immediately following it.
   */
  stream(options?: {
    streamId?: string;
    eventId?: string;
  }): AsyncIterableIterator<AgentEvent>;

  /** Abort any active streams. */
  abort(): Promise<void>;

  /** The complete, ordered history of events across all streams. */
  readonly events: AgentEvent[];
}
